// Posts from Split Out
const media = $('Split Out').all().map(i => i.json);
// Insights from Get Post Insights
const insightItems = $input.all();

// Build a lookup by media id so order and failures don't matter.
// Requires the insights node to expose the media id (see "How to verify").
const insightsById = new Map();
const errors = [];

insightItems.forEach((item, idx) => {
  const j = item.json || {};
  const id = j._media_id || j.media_id || media[idx]?.id; // fallback: index
  if (!id) return;
  if (j.error) {
    errors.push({ id, code: j.error.code, message: j.error.message });
    return;
  }
  insightsById.set(id, j);
});

const metric = (res, name) => {
  const m = (res?.data || []).find(d => d.name === name);
  if (!m) return null;
  return m.total_value?.value ?? m.values?.[0]?.value ?? null;
};

const sum = (...vals) => vals.reduce((a, v) => a + (v ?? 0), 0);

const posts = media.map(m => {
  const ins = insightsById.get(m.id) || {};
  const likes = m.like_count ?? null;
  const comments = m.comments_count ?? null;
  const shares = metric(ins, 'shares');
  const saves = metric(ins, 'saved');
  const reach = metric(ins, 'reach');
  const views = metric(ins, 'views') ?? metric(ins, 'plays');

  // Engagement from whatever is available, flagged when partial
  const hasAll = [likes, comments, shares, saves].every(v => v !== null);
  const engagement = sum(likes, comments, shares, saves);

  return {
    id: m.id,
    timestamp: m.timestamp,
    media_type: m.media_type,
    permalink: m.permalink,
    caption: (m.caption || '').slice(0, 120),
    likes, comments, shares, saves, reach, views,
    engagement,
    engagement_complete: hasAll,
    er_reach_pct: reach > 0 ? +(engagement / reach * 100).toFixed(2) : null
  };
}).filter(p => p.id);

if (posts.length === 0) {
  throw new Error('No posts built. Check Split Out and Get Post Insights output.');
}

// Data-quality summary
const withReach = posts.filter(p => p.reach !== null).length;
const withViews = posts.filter(p => p.views !== null).length;
const reachAvailable = withReach > 0;

// Ranking: reach-based ER if available, otherwise absolute engagement
const rankKey = reachAvailable ? 'er_reach_pct' : 'engagement';
const ranked = posts
  .filter(p => p[rankKey] !== null)
  .sort((a, b) => b[rankKey] - a[rankKey]);

const n = Math.max(1, Math.round(ranked.length * 0.2));
const top = ranked.slice(0, n);
const bottom = ranked.length >= 10 ? ranked.slice(-n).reverse() : [];

const prompt =
`Account niche: Family & Kids Comedy (AI-generated entertainment)
Goal: Grow followers and reach
Posts analysed: ${posts.length} (last 30 fetched)
Engagement rate denominator: ${reachAvailable ? 'reach' : 'UNAVAILABLE - ranking by absolute engagement'}

DATA QUALITY:
- Posts with reach: ${withReach}/${posts.length}
- Posts with views: ${withViews}/${posts.length}
- Insight API errors: ${JSON.stringify(errors.slice(0, 5))}
- Ranking metric: ${rankKey}

TOP 20%:
${JSON.stringify(top)}

BOTTOM 20%:
${JSON.stringify(bottom)}

ALL POSTS:
${JSON.stringify(posts)}

Follow your instructions and produce the weekly report.`;

return [{
  json: {
    prompt,
    post_count: posts.length,
    reach_available: reachAvailable,
    insight_errors: errors.length
  }
}];
